export function getItem(slug: string): ItemData | undefined {
  return ALL_ITEMS.find(i => i.slug === slug);
}

export function searchItems(query: string): ItemData[] {
  if (!query.trim()) return ALL_ITEMS;
  const q = query.toLowerCase();
  return ALL_ITEMS.filter(item =>
    item.name.toLowerCase().includes(q) ||
    item.category.toLowerCase().includes(q) ||
    item.description.toLowerCase().includes(q) ||
    item.aliases.some(a => a.toLowerCase().includes(q)) ||
    item.keywords.some(k => k.toLowerCase().includes(q))
  );
}

export function getItemsByCategory(category: string): ItemData[] {
  return ALL_ITEMS.filter(i => i.category.toLowerCase() === category.toLowerCase());
}

export const CATEGORIES = [
  ...new Set(ALL_ITEMS.map(i => i.category))
].sort();

